async function viewReview(e){const t=await api("/review"),a=t.money||{},n="ro"===LANG,s=t.changed.filter(e=>"watch_new"===e.kind),i=t.changed.filter(e=>"watch_new"!==e.kind),o=t.week||{spent:0,income:0,top:[]};e.innerHTML=`<div class="pagehead"><div><h1>${tr("This week")}</h1>\n      <p>${t.first_time?tr("Everything below is from the last seven days. Once you tick this off, next time shows only what is new since then."):`${tr("What changed since")} ${fdate(String(t.since).slice(0,10))}`}</p></div></div>\n\n    <section class="card"><h3 style="margin-top:0">1 · ${n?"Banii":"The money"}</h3>\n    <div class="revweek">\n      <div><span class="muted">${n?"Au ieșit":"Went out"}</span><b class="amount">${money(o.spent)}</b></div>\n      <div><span class="muted">${n?"Au intrat":"Came in"}</span><b class="amount">${money(o.income)}</b></div>\n    </div>\n    ${o.top.length?`<p class="muted" style="margin:8px 0 0">${n?"Cel mai mult":"Most of it"}: ${o.top.map(e=>`${esc(tr(e.category))} ${money(e.total)}`).join(" · ")}</p>`:""}\n    ${a.needs_balance?`<p class="muted" style="margin:12px 0 0">${tr("Enter what is in the account on the dashboard and this answers itself.")}</p>`:`<p class="revmoney ${a.low<0?"neg":""}" style="margin:12px 0 0">\n          ${a.low<a.now?`${tr("Lowest point:")} <b>${money(a.low)}</b> ${tr("on")} ${fdate(a.low_date)}`:tr("Nothing due drops the balance below where it is now.")}</p>\n        <p class="muted" style="margin:8px 0 0">${tr("now")} ${money(a.now)}${a.stale_days>7?` · <a href="#dashboard">${tr("the balance is old — update it")}</a>`:""}</p>`}</section>\n\n    <section class="card" style="margin-top:16px"><h3 style="margin-top:0">2 · ${tr("What needs you")}</h3>\n    ${t.decide.length?`<table class="cards"><tbody>${t.decide.map(e=>{const t=e.date?`<span class="muted">${fdate(e.date)}</span>`:"",a=null!=e.amount?`<span class="amount">${Number(e.amount).toLocaleString("ro-RO",{minimumFractionDigits:2,maximumFractionDigits:2})} ${esc(e.currency||cur())}</span>`:"",n={confirm_charge:`<button class="btn small" data-confirm="${e.id}" data-prop="${e.property_id}">${tr("Confirm")}</button>`,pay_bill:`<button class="btn small" data-paybill="${e.id}">${tr("Mark as paid")}</button>`,todo:`<button class="btn small" data-todo="${e.id}">${tr("Done")}</button>`}[e.kind]||"";return`<tr>\n      <td><b>${esc(e.label)}</b>${e.entity?`<br><span class="muted">${esc(e.entity)}</span>`:""}</td>\n      <td>${t}</td><td class="right">${a}</td>\n      <td class="right">${canWrite()?n:""}</td></tr>`}).join("")}</tbody></table>`:`<p class="muted" style="margin:0">${tr("Nothing is waiting on a decision.")}</p>`}\n    ${t.open_maintenance||t.meters_pending?`<p class="muted" style="margin:12px 0 0">\n      ${t.open_maintenance?`<a href="#properties">${tr("Repairs still open")}: ${t.open_maintenance}</a>`:""}\n      ${t.open_maintenance&&t.meters_pending?" · ":""}\n      ${t.meters_pending?`<a href="#properties">${tr("Readings still missing")}: ${t.meters_pending}</a>`:""}</p>`:""}</section>\n\n    <section class="card" style="margin-top:16px"><h3 style="margin-top:0">3 · ${tr("What changed")}</h3>\n    ${i.length?`<ul class="revlist">${i.map(e=>`<li>${(e=>({reading_in:`${tr("Reading came in")}: ${esc(tr(e.label))}${e.value?` — ${esc(e.value)}`:""}`,maintenance_new:`${tr("Reported broken")}: ${esc(e.label)}`,watch_new:`${tr("New notice")}: ${esc(e.label)}`,bill_paid:`${tr("Bill paid")}: ${esc(e.label)}`}[e.kind]||esc(e.label)))(e)}</li>`).join("")}</ul>`:`<p class="muted" style="margin:0">${tr("Nothing happened while you were away.")}</p>`}</section>\n\n    ${s.length?`<details class="card foldcard" style="margin-top:16px"><summary>${n?`Anunțuri de pe paginile urmărite (${s.length})`:`Notices from watched pages (${s.length})`}</summary>\n      <ul class="revlist" style="padding-top:12px">${s.map(e=>`<li>${esc(e.label)}${e.entity?` <span class="muted">· ${esc(e.entity)}</span>`:""}</li>`).join("")}</ul>\n      <p style="margin:8px 0 0"><a href="#watch">${n?"Deschide paginile urmărite":"Open watched pages"}</a></p>\n    </details>`:""}\n\n    ${canWrite()?`<div class="row" style="justify-content:center;margin-top:24px">\n      <button class="btn" id="revdone" style="min-width:220px">${tr("Done for this week")}</button></div>`:""}`;const l=()=>viewReview(e);e.querySelectorAll("[data-confirm]").forEach(e=>e.onclick=async()=>{try{await api(`/properties/${e.dataset.prop}/charges/${e.dataset.confirm}/confirm`,{method:"POST"}),toast(tr("Payment confirmed"),"success"),l()}catch(e){toast(e.message)}}),e.querySelectorAll("[data-paybill]").forEach(e=>e.onclick=async()=>{try{await api(`/bills/${e.dataset.paybill}/pay`,{method:"POST"}),toast(tr("Marked as paid"),"success"),l()}catch(e){toast(e.message)}}),e.querySelectorAll("[data-todo]").forEach(e=>e.onclick=async()=>{try{await api(`/todos/${e.dataset.todo}/toggle`,{method:"POST"}),l()}catch(e){toast(e.message)}}),$("#revdone")?.addEventListener("click",async()=>{try{await api("/review/done",{method:"POST"}),toast(tr("See you next week"),"success"),location.hash="#dashboard"}catch(e){toast(e.message)}})}